package io.github.diodeme.ji.artifact.fs;

import java.util.Map;

/** Structured refusal to start with invalid database-referenced artifacts. */
public final class ArtifactStartupException extends RuntimeException {
    @java.io.Serial private static final long serialVersionUID = 1L;
    private final String code;
    private final transient Map<String, String> parameters;

    ArtifactStartupException(String code, Map<String, String> parameters) {
        super(code);
        this.code = code;
        this.parameters = Map.copyOf(parameters);
    }

    public String code() { return code; }
    public Map<String, String> parameters() { return parameters; }
}
